def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    desperate_opp = 0
    rich_opp = 0
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 180:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if len(alive) == 0:
        return float(min(budget, 18.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (25.0 - float(supply)) / 10.0
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    elif hp <= 6:
        urgency += 0.2

    if no_water_days >= 2:
        urgency += 1.0
    elif no_water_days >= 1:
        urgency += 0.45

    urgency += scarcity * 0.55

    if hp <= 2 or no_water_days >= 2:
        bid = max(0.92 * DAILY_SALARY, avg_prev + 8.0, 72.0)
    elif hp <= 4 or no_water_days >= 1:
        if max_prev >= 150:
            bid = 58.0 + 10.0 * scarcity
        else:
            bid = max(52.0 + 12.0 * scarcity, avg_prev + 3.0)
    else:
        if supply >= 22:
            bid = 12.0 + 6.0 * scarcity
        elif supply >= 19:
            if max_prev >= 150:
                bid = 22.0 + 8.0 * scarcity
            else:
                bid = max(26.0 + 10.0 * scarcity, min(max_prev + 1.5, 48.0))
        else:
            if max_prev >= 150:
                bid = 34.0 + 12.0 * scarcity
            else:
                bid = max(38.0 + 12.0 * scarcity, min(max_prev + 2.0, 62.0))

    if desperate_opp >= 2 and urgency < 0.8:
        bid *= 0.88
    if rich_opp >= 2 and scarcity > 0.5 and urgency > 0.4:
        bid += 6.0

    reserve = 0.0
    if day <= 3:
        reserve = 110.0
    elif day <= 6:
        reserve = 70.0
    else:
        reserve = 25.0

    max_affordable = budget - reserve
    if urgency >= 1.0:
        max_affordable = budget
    elif max_affordable < 0:
        max_affordable = budget * 0.45

    if hp >= 7 and supply >= 22 and max_prev >= 160:
        bid = min(bid, 18.0)

    if bid < 0:
        bid = 0.0
    bid = min(float(bid), float(max_affordable), float(budget))

    if urgency >= 1.0 and bid < min(budget, 60.0):
        bid = min(float(budget), 60.0)

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive = [o for o in opponents_status.values() if o['alive']]
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    no_water = my_status['no_water_days']

    # Get yesterday's max bid from alive opponents with trace
    max_prev = None
    for opp in alive:
        trace = opp.get('previous_trace', {})
        if trace and 'bid' in trace and trace['bid'] is not None:
            if max_prev is None or trace['bid'] > max_prev:
                max_prev = trace['bid']

    # Emergency bids if low HP or many days without water
    if my_hp <= 2 or no_water >= 2:
        return min(my_budget, DAILY_SALARY * 0.95)
    if my_hp <= 4:
        return min(my_budget, DAILY_SALARY * 0.75)

    # Normal case: use yesterday's info if available
    if max_prev is not None:
        # Slightly outbid, but cap at budget and not more than 85% of salary
        bid = min(my_budget, max(DAILY_SALARY * 0.5, max_prev + 1.5))
        return bid

    # First day or no trace: conservative bid
    return min(my_budget, DAILY_SALARY * 0.5)
